let currentCategory="";

const fallbackImage="shop_image.jpeg";
let detailBackPage="homePage";

function scrollToTop(){

window.scrollTo({top:0,left:0,behavior:"auto"});

}




window.onload=function(){

setTimeout(()=>{

document.getElementById("splash").style.display="none";

},1000);

};


/* Category */

function showCategory(category){

currentCategory=category;

scrollToTop();

document.getElementById("homePage").classList.add("hidden");

document.getElementById("searchPage").classList.add("hidden");

document.getElementById("productPage").classList.remove("hidden");

document.getElementById("categoryTitle").innerText=category;

let filterProducts=products.filter(p=>p.category===category);

displayProducts(filterProducts,"productGrid");

}


/* Display Products */

function displayProducts(data,container){

let html="";

data.forEach(p=>{

html+=`

<div class="product" onclick="showDetail(${p.id})">

<img src="${p.image}" onerror="this.onerror=null;this.src='${fallbackImage}'" alt="${p.name}">

<h3>${p.name}</h3>

<div class="price-row">

    <h5 class="oldprice">
        <del>₹${p.oldPrice}</del>
    </h5>

    <p>₹${p.price}</p>

</div>


<h4>${p.discount}</h4>

</div>

`;

});

document.getElementById(container).innerHTML=html;

}


/* Product Detail */

function showDetail(id){

    let p = products.find(product => product.id === Number(id));

    if(!p){
        console.error("Product not found:", id);
        return;
    }

    // Remember where the user came from.
    if(!document.getElementById("productPage").classList.contains("hidden")){
        detailBackPage = "productPage";
    }else if(!document.getElementById("searchPage").classList.contains("hidden")){
        detailBackPage = "searchPage";
    }else{
        detailBackPage = "homePage";
    }

    scrollToTop();

    document.getElementById("homePage").classList.add("hidden");
    document.getElementById("productPage").classList.add("hidden");
    document.getElementById("searchPage").classList.add("hidden");
    document.getElementById("detailPage").classList.remove("hidden");

    document.getElementById("productDetail").innerHTML = `

        <img
            src="${p.image}"
            class="detail-img"
            onerror="this.onerror=null;this.src='${fallbackImage}'"
            alt="${p.name}"
        >

        <h2 class="detail-title">${p.name}</h2>

        <div class="detailPagePrice">
            ${p.oldPrice ? `
                <p class="detail-oldprice">
                    <del>₹${p.oldPrice}</del>
                </p>
            ` : ""}

            <p class="detail-price">₹${p.price}</p>
        </div>

        ${p.discount ? `
            <h4 class="detail-discount">${p.discount}</h4>
        ` : ""}

        <p class="detail-desc">${p.description || "Premium cricket equipment from S.A SPORTS."}</p>

        <a
            class="whatsapp"
            target="_blank"
            rel="noopener"
            href="https://wa.me/919600004723?text=Hello%20S.A%20SPORTS%2C%20I%20am%20interested%20in%20${encodeURIComponent(p.name)}"
        >
            Enquire on WhatsApp
        </a>
    `;
}

/* Back */

function goHome(){

scrollToTop();

document.getElementById("homePage").classList.remove("hidden");

document.getElementById("productPage").classList.add("hidden");

document.getElementById("detailPage").classList.add("hidden");

document.getElementById("searchPage").classList.add("hidden");

document.getElementById("searchInput").value="";

}


function goBackProducts(){

scrollToTop();

document.getElementById("detailPage").classList.add("hidden");
document.getElementById("productPage").classList.add("hidden");
document.getElementById("searchPage").classList.add("hidden");
document.getElementById("homePage").classList.add("hidden");
document.getElementById(detailBackPage).classList.remove("hidden");

}


/* Search */

function searchOffer(searchText){

document.getElementById("searchInput").value=searchText;

searchProduct();

}

function normalizeSearchText(value){

return value.toLowerCase().trim().split(/\s+/).map(word=>
word.length>3 && word.endsWith("s") ? word.slice(0,-1) : word
).join(" ");

}

function searchProduct(){

let text=normalizeSearchText(document.getElementById("searchInput").value);

if(text===""){

goHome();

return;
}

scrollToTop();

document.getElementById("homePage").classList.add("hidden");

document.getElementById("productPage").classList.add("hidden");

document.getElementById("detailPage").classList.add("hidden");

document.getElementById("searchPage").classList.remove("hidden");

let result=products.filter(p=>

normalizeSearchText(p.name).includes(text) ||

normalizeSearchText(p.category).includes(text) ||

normalizeSearchText(p.description).includes(text)

);

displayProducts(result,"searchResults");

}
